def cellpath(g,s,t):
 R=len(g);C=len(g[0]); q=deque([s]);pr={s:None}
 while q:
  p=q.popleft()
  if p==t:break
  for dr,dc in ((1,0),(0,1),(-1,0),(0,-1)):
   z=(p[0]+dr,p[1]+dc)
   if 0<=z[0]<R and 0<=z[1]<C and g[z[0]][z[1]]!=3 and z not in pr:
    pr[z]=p;q.append(z)
 if t not in pr:return None
 path=[];p=t
 while p is not None:path.append(p);p=pr[p]
 return path[::-1]
